class TestRunner:
    """테스트 실행자"""

    def __init__(self, code: str):
        self.code = code
        self.results = []

    def run_tests(self, test_cases: List[Dict[str, Any]]) -> List[TestResult]:
        """테스트 케이스 실행"""
        self.results = []

        for test in test_cases:
            test_name = test.get("name", "unknown")
            assertions = test.get("assertions", [])

            passed = True
            error_msg = ""

            # 각 assertion 검사
            for assertion in assertions:
                assertion_type = assertion.get("type")
                assertion_value = assertion.get("value")

                # 코드에서 assertion 검증
                if assertion_type == "contains":
                    if assertion_value not in self.code:
                        passed = False
                        error_msg = f"Missing: {assertion_value}"
                        break
                elif assertion_type == "has_function":
                    if f"fn {assertion_value}(" not in self.code:
                        passed = False
                        error_msg = f"Missing function: {assertion_value}"
                        break
                elif assertion_type == "has_struct":
                    if f"struct {assertion_value}" not in self.code:
                        passed = False
                        error_msg = f"Missing struct: {assertion_value}"
                        break

            result = TestResult(
                test_name=test_name,
                passed=passed,
                error_msg=error_msg,
            )
            self.results.append(result)

        return self.results

    def get_pass_rate(self) -> float:
        """테스트 통과율"""
        if not self.results:
            return 0.0
        passed = sum(1 for r in self.results if r.passed)
        return passed / len(self.results)


class HealingSurgeon:
    """자동 버그 수정 에이전트"""

    def __init__(self, code: str, test_cases: List[Dict[str, Any]]):
        self.code = code
        self.test_cases = test_cases
        self.proof_score = None
        self.is_healed = False

    def diagnose(self) -> Dict[str, Any]:
        """문제 진단"""
        compilation_ok, comp_msg = CodeAnalyzer.check_compilation(self.code)
        type_safe, type_msg = CodeAnalyzer.check_type_safety(self.code)
        struct_ok, struct_msg = CodeAnalyzer.check_structure(self.code)

        return {
            "compilation": {"ok": compilation_ok, "message": comp_msg},
            "type_safety": {"ok": type_safe, "message": type_msg},
            "structure": {"ok": struct_ok, "message": struct_msg},
        }

    def heal(self) -> Tuple[str, ProofScore]:
        """자동 치료 (버그 수정)"""
        # Step 1: 테스트 실행
        runner = TestRunner(self.code)
        runner.run_tests(self.test_cases)
        test_pass_rate = runner.get_pass_rate()

        # Step 2: 진단
        diagnosis = self.diagnose()

        # Step 3: 신뢰도 점수 계산
        code_comp = 1.0 if diagnosis["compilation"]["ok"] else 0.5
        type_safety = 1.0 if diagnosis["type_safety"]["ok"] else 0.7
        struct = 1.0 if diagnosis["structure"]["ok"] else 0.6

        proof = ProofScore(
            code_compilation=code_comp,
            test_pass_rate=test_pass_rate,
            type_safety=type_safety,
            structure_quality=struct,
        )

        self.proof_score = proof

        # Step 4: 자동 수정 (간단한 버전)
        healed_code = self.code
        if not diagnosis["compilation"]["ok"]:
            healed_code = self._fix_braces(healed_code)

        if not diagnosis["type_safety"]["ok"]:
            healed_code = self._add_type_hints(healed_code)

        self.code = healed_code
        self.is_healed = True

        return healed_code, proof

    def _fix_braces(self, code: str) -> str:
        """괄호 수정"""
        open_count = code.count("{")
        close_count = code.count("}")

        if open_count > close_count:
            code += "\n}" * (open_count - close_count)
        return code

    def _add_type_hints(self, code: str) -> str:
        """타입 힌트 추가"""
        if "fn " in code and "->" not in code:
            # 기본 타입 힌트 추가 (간단한 버전)
            code = code.replace(
                "fn new(",
                "fn new(name: string) -> Result<i64, string>"
            )
        return code


def main():
    """테스트 실행"""
    print("=== Phase 0 Day 5: Healing Surgeon ===\n")

    # Test 1: TODO 앱 테스트
    test1_code = """// Module: todo_app
use std:io;

struct TodoList {
    id: i64,
    name: string,
    status: string,
}

fn new(name: string) -> Result<i64, string> {
    if name.len() == 0 {
        return Err("Name cannot be empty".to_string());
    }
    return Ok(1 as i64);
}

fn delete_todo(id: i64) -> string {
    return format!("Deleted: {}", id);
}
"""

    test1_cases = [
        {
            "name": "Compilation Test",
            "assertions": [
                {"type": "contains", "value": "struct TodoList"},
                {"type": "has_function", "value": "new"},
            ],
        },
        {
            "name": "Type Safety Test",
            "assertions": [
                {"type": "contains", "value": "string"},
                {"type": "contains", "value": "i64"},
            ],
        },
        {
            "name": "Structure Test",
            "assertions": [
                {"type": "has_struct", "value": "TodoList"},
                {"type": "has_function", "value": "delete_todo"},
            ],
        },
    ]

    print("=== Test 1: TODO 앱 Self-Healing ===")
    surgeon1 = HealingSurgeon(test1_code, test1_cases)
    healed_code1, proof1 = surgeon1.heal()

    print(f"✓ Diagnosis:")
    diagnosis1 = surgeon1.diagnose()
    for check, result in diagnosis1.items():
        status = "✓" if result["ok"] else "✗"
        print(f"  {status} {check}: {result['message']}")

    print(f"\n✓ ProofScore: {proof1.total:.2f}")
    print(f"  - Compilation: {proof1.code_compilation:.2f}")
    print(f"  - Test Pass Rate: {proof1.test_pass_rate:.2f}")
    print(f"  - Type Safety: {proof1.type_safety:.2f}")
    print(f"  - Structure: {proof1.structure_quality:.2f}")
    print()

    # Test 2: 웹 서버 (더 복잡한 케이스)
    test2_code = """// Module: web_server
use std:io;
use std:concurrent;

struct Router {
    id: i64,
    name: string,
}

struct Handler {
    id: i64,
}

fn new(name: string) -> Result<i64, string> {
    return Ok(1);
}

fn routing() -> string {
    return "Route".to_string();
}
"""

    test2_cases = [
        {
            "name": "Complex Compilation",
            "assertions": [
                {"type": "has_struct", "value": "Router"},
                {"type": "has_struct", "value": "Handler"},
            ],
        },
        {
            "name": "Multiple Functions",
            "assertions": [
                {"type": "has_function", "value": "new"},
                {"type": "has_function", "value": "routing"},
            ],
        },
    ]

    print("=== Test 2: 웹 서버 Self-Healing ===")
    surgeon2 = HealingSurgeon(test2_code, test2_cases)
    healed_code2, proof2 = surgeon2.heal()

    print(f"✓ Diagnosis:")
    diagnosis2 = surgeon2.diagnose()
    for check, result in diagnosis2.items():
        status = "✓" if result["ok"] else "✗"
        print(f"  {status} {check}: {result['message']}")

    print(f"\n✓ ProofScore: {proof2.total:.2f}")
    print(f"  - Compilation: {proof2.code_compilation:.2f}")
    print(f"  - Test Pass Rate: {proof2.test_pass_rate:.2f}")
    print(f"  - Type Safety: {proof2.type_safety:.2f}")
    print(f"  - Structure: {proof2.structure_quality:.2f}")
    print()

    # Validation
    passed = 0
    total = 2

    if proof1.total >= 0.75:
        passed += 1
        print("✅ Test 1 PASSED")
    else:
        print(f"❌ Test 1 FAILED (ProofScore: {proof1.total:.2f})")

    if proof2.total >= 0.75:
        passed += 1
        print("✅ Test 2 PASSED")
    else:
        print(f"❌ Test 2 FAILED (ProofScore: {proof2.total:.2f})")

    print(f"\n✅ {passed}/{total} 테스트 완료!")

    accuracy = (passed / total) * 100
    if accuracy >= 90:
        print("✨ Self-Healing 정확도: 90%+ (SUCCESS!)")
        return 0
    else:
        print(f"⚠️ Self-Healing 정확도: {accuracy:.0f}%")
        return 1


if __name__ == "__main__":
    exit(main())

#!/usr/bin/env python3
"""
Intelligent Code Generator - Stage 3 최종 통합

SystemArchitecture → 전체 코드 생성
- FV-Lang 모듈 (구조체, 함수, 보안)
- 테스트 케이스 (HealingSurgeon 호환)
- Docker Compose 배포
- ProofScore 계산
"""

from typing import List, Dict
from dataclasses import dataclass, field
import sys
import os

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from architecture_designer import (
    SystemArchitecture, DataEntity, MicroService, ServiceEndpoint
)
from fvlang_type_mapper import FVLangTypeMapper, DataField
from pattern_selector import PatternSelector
from test_codegen import TestCodeGenerator
from deployment_codegen import DeploymentConfigGenerator


@dataclass
class FVLangModule:
    """FV-Lang 모듈"""
    name: str              # "user_service", "shared"
    imports: List[str] = field(default_factory=list)
    structs: List[str] = field(default_factory=list)
    functions: List[str] = field(default_factory=list)

    def to_code(self) -> str:
        """모듈을 FV-Lang 코드로 변환"""
        lines = []

        # 임포트
        if self.imports:
            for imp in self.imports:
                lines.append(f"use {imp};")
            lines.append("")

        # 구조체
        if self.structs:
            for struct in self.structs:
                lines.append(struct)
                lines.append("")

        # 함수
        if self.functions:
            for func in self.functions:
                lines.append(func)
                lines.append("")

        return "\n".join(lines)


@dataclass
class GeneratedCode:
    """최종 생성 코드"""
    modules: List[FVLangModule]
    test_cases: List[Dict]
    deployment_config: str
    generation_metadata: Dict


class IntelligentCodeGenerator:
    """Stage 3 최종 오케스트레이터"""

    def __init__(self):
        """초기화"""
        self.type_mapper = FVLangTypeMapper()
        self.pattern_selector = PatternSelector()
        self.test_generator = TestCodeGenerator()
        self.deployment_generator = DeploymentConfigGenerator()

    def generate(self, architecture: SystemArchitecture) -> GeneratedCode:
        """
        SystemArchitecture → GeneratedCode

        처리 흐름:
        1. 패턴 선택
        2. 공유 모듈 생성 (엔티티 + Factory)
        3. 서비스 모듈 생성
        4. 보안 검사 추가
        5. 테스트 케이스 생성
        6. Docker Compose 생성
        7. ProofScore 계산
        """
        print("⚙️  Stage 3: Intelligent Code Generator 실행")
        print()

        # [Step 1] 패턴 선택
        patterns = self.pattern_selector.select_patterns(architecture)
        applicable_patterns = [name for name, decision in patterns.items() if decision.applies]
        print(f"[Step 1] 패턴 선택: {len(applicable_patterns)}개")
        for pattern in applicable_patterns:
            print(f"  ✓ {pattern}")
        print()

        # [Step 2] 공유 모듈 생성
        shared_module = self._generate_shared_module(
            architecture.data_model, applicable_patterns
        )
        print(f"[Step 2] 공유 모듈 생성")
        print(f"  - {len(architecture.data_model.entities)}개 struct")
        print(f"  - {len(shared_module.functions)}개 함수")
        print()

        # [Step 3] 서비스 모듈 생성
        service_modules = []
        for service in architecture.services.services:
            module = self._generate_service_module(
                service, architecture, applicable_patterns
            )
            service_modules.append(module)
            print(f"[Step 3] {service.name} 모듈 생성")
            print(f"  - {len(module.functions)}개 함수")

        print()

        # [Step 4] 보안 검사 추가
        print(f"[Step 4] 보안 검사 추가")
        for i, module in enumerate([shared_module] + service_modules):
            self._add_security_checks(module, architecture.security_controls)
        print(f"  ✓ 모든 모듈에 보안 검사 추가")
        print()

        # [Step 5] 테스트 케이스 생성
        test_cases = self.test_generator.generate_all(architecture)
        print(f"[Step 5] 테스트 케이스 생성: {len(test_cases)}개")
        print()

        # [Step 6] Docker Compose 생성
        docker_compose = self.deployment_generator.generate_docker_compose(architecture)
        print(f"[Step 6] Docker Compose 생성")
        print(f"  - {len(docker_compose.split(chr(10)))}줄")
        print()

        # [Step 7] 메타데이터
        metadata = {
            "patterns": applicable_patterns,
            "services": len(architecture.services.services),
            "entities": len(architecture.data_model.entities),
            "total_functions": sum(len(m.functions) for m in [shared_module] + service_modules),
            "test_cases": len(test_cases),
        }
        print(f"[Step 7] 메타데이터")
        print(f"  - {metadata['services']}개 서비스")
        print(f"  - {metadata['entities']}개 엔티티")
        print(f"  - {metadata['total_functions']}개 함수")
        print()

        # GeneratedCode 반환
        all_modules = [shared_module] + service_modules

        return GeneratedCode(
            modules=all_modules,
            test_cases=test_cases,
            deployment_config=docker_compose,
            generation_metadata=metadata
        )

    def _generate_shared_module(self, data_model, patterns: List[str]) -> FVLangModule:
        """공유 모듈 생성 (엔티티 정의 + Factory)"""
        module = FVLangModule(name="shared")

        # [1] struct 생성
        for entity in data_model.entities:
            struct_code = self._entity_to_struct(entity)
            module.structs.append(struct_code)

        # [2] Factory 함수 (패턴 적용 시)
        if "Factory" in patterns:
            for entity in data_model.entities:
                factory_fn = self._generate_factory_function(entity)
                module.functions.append(factory_fn)

        # [3] Builder 함수 (패턴 적용 시)
        if "Builder" in patterns:
            for entity in data_model.entities:
                if len(entity.fields) >= 5:
                    builder_fn = self._generate_builder_function(entity)
                    module.functions.append(builder_fn)

        # [4] Singleton 캐시 (패턴 적용 시)
        if "Singleton" in patterns:
            singleton_fn = self._generate_singleton_cache()
            module.functions.append(singleton_fn)

        return module

    def _entity_to_struct(self, entity: DataEntity) -> str:
        """엔티티 → struct 정의"""
        lines = [f"struct {entity.name} {{"]

        for field in entity.fields:
            # DataField로 변환 (간단히)
            fv_type = self.type_mapper.map_base_type(field.type)

            if field.nullable:
                fv_type = f"Option<{fv_type}>"

            hints = []
            if field.indexed:
                hints.append("indexed")
            if field.unique:
                hints.append("unique")

            hint_str = f"  // {', '.join(hints)}" if hints else ""
            lines.append(f"    {field.name}: {fv_type},{hint_str}")

        lines.append("}")
        return "\n".join(lines)

    def _generate_factory_function(self, entity: DataEntity) -> str:
        """Factory 함수 생성"""
        entity_lower = entity.name.lower()
        lines = [
            f"fn create_{entity_lower}(",
            "    // 필드 인자들",
            f") -> {entity.name} {{",
            f"    return {entity.name} {{",
        ]

        for field in entity.fields:
            lines.append(f"        {field.name}: {field.name},")

        lines.append("    };")
        lines.append("}")

        return "\n".join(lines)

    def _generate_builder_function(self, entity: DataEntity) -> str:
        """Builder 함수 생성"""
        entity_lower = entity.name.lower()
        lines = [
            f"struct {entity.name}Builder {{",
        ]

        for field in entity.fields:
            fv_type = self.type_mapper.map_base_type(field.type)
            if field.nullable:
                fv_type = f"Option<{fv_type}>"
            lines.append(f"    {field.name}: {fv_type},")

        lines.append("}")
        lines.append("")
        lines.append(f"impl {entity.name}Builder {{")
        lines.append(f"    fn build(self) -> Result<{entity.name}, Error> {{")
        lines.append(f"        return Ok({entity.name} {{")
        for field in entity.fields:
            lines.append(f"            {field.name}: self.{field.name},")
        lines.append("        });")
        lines.append("    }")
        lines.append("}")

        return "\n".join(lines)

    def _generate_singleton_cache(self) -> str:
        """Singleton 캐시 함수"""
        lines = [
            "fn get_cache_instance() -> Rc<RefCell<HashMap<string, string>>> {",
            "    // 캐시 초기화 (한 번만 실행)",
            "    static CACHE: Rc<RefCell<HashMap<string, string>>> = Rc::new(RefCell::new(HashMap::new()));",
            "    return CACHE;",
            "}",
        ]
        return "\n".join(lines)

    def _generate_service_module(
        self,
        service: MicroService,
        architecture: SystemArchitecture,
        patterns: List[str]
    ) -> FVLangModule:
        """서비스 모듈 생성"""
        module = FVLangModule(name=service.name)

        # [1] API 엔드포인트 함수
        for endpoint in service.api_endpoints:
            fn_code = self._endpoint_to_function(endpoint)
            module.functions.append(fn_code)

        # [2] Repository 함수 (DB 사용 서비스)
        if "Repository" in patterns and service.database and service.database != "none":
            for entity in architecture.data_model.entities:
                repo_funcs = self._generate_repository_functions(entity)
                module.functions.extend(repo_funcs)

        # [3] 캐싱 함수
        for entity in architecture.data_model.entities:
            if entity.cache_strategy and entity.cache_strategy != "none":
                cache_funcs = self._generate_cache_functions(entity)
                module.functions.extend(cache_funcs)

        # [4] 이벤트 함수 (queue 사용 서비스)
        if service.queue and service.queue != "none":
            event_funcs = self._generate_event_functions(service)
            module.functions.extend(event_funcs)

        return module

    def _endpoint_to_function(self, endpoint: ServiceEndpoint) -> str:
        """엔드포인트 → 함수"""
        method = endpoint.method.lower()
        path = endpoint.path.strip('/').replace('/', '_')
        fn_name = f"{method}_{path}"

        # 파라미터
        params = []
        if endpoint.request_schema:
            for key, field_type in endpoint.request_schema.items():
                fv_type = self.type_mapper.map_base_type(field_type)
                params.append(f"{key}: {fv_type}")

        params_str = ", ".join(params) if params else ""

        # 반환값
        if endpoint.response_schema:
            response_type = self.type_mapper.format_response_schema_to_type(endpoint.response_schema)
        else:
            response_type = "string"

        lines = [
            f"fn {fn_name}({params_str}) -> Result<{response_type}, Error> {{",
            "    // ratelimit: 100/min",
            "    return Err(\"not_implemented\".to_string());",
            "}",
        ]

        return "\n".join(lines)

    def _generate_repository_functions(self, entity: DataEntity) -> List[str]:
        """Repository 함수 생성 (find_by_id, save, delete)"""
        entity_lower = entity.name.lower()
        funcs = []

        # find_by_id
        funcs.append(f"""fn find_{entity_lower}_by_id(id: string) -> Result<{entity.name}, Error> {{
    // DB 조회 로직
    return Err("not_found".to_string());
}}""")

        # save
        funcs.append(f"""fn save_{entity_lower}(item: {entity.name}) -> Result<string, Error> {{
    // DB 저장 로직
    return Ok(item.id);
}}""")

        # delete
        funcs.append(f"""fn delete_{entity_lower}(id: string) -> Result<bool, Error> {{
    // DB 삭제 로직
    return Ok(true);
}}""")

        return funcs

    def _generate_cache_functions(self, entity: DataEntity) -> List[str]:
        """캐싱 함수 생성 (get_cached, set_cached)"""
        entity_lower = entity.name.lower()
        funcs = []

        # get_cached
        funcs.append(f"""fn get_cached_{entity_lower}(id: string) -> Result<Option<{entity.name}>, Error> {{
    // Redis 캐시 조회
    return Ok(None);
}}""")

        # set_cached
        funcs.append(f"""fn set_cached_{entity_lower}(id: string, item: {entity.name}) -> Result<bool, Error> {{
    // Redis 캐시 저장 (TTL: 1h)
    return Ok(true);
}}""")

        return funcs

    def _generate_event_functions(self, service: MicroService) -> List[str]:
        """이벤트 함수 생성 (publish, consume)"""
        funcs = []

        # publish_event
        funcs.append(f"""fn publish_event(event_type: string, payload: string) -> Result<bool, Error> {{
    // 이벤트 발행 ({service.queue})
    return Ok(true);
}}""")

        # consume_events
        funcs.append(f"""fn consume_events(handler: fn(string) -> Result<(), Error>) -> Result<(), Error> {{
    // 이벤트 소비
    return Ok(());
}}""")

        return funcs

    def _add_security_checks(self, module: FVLangModule, security_controls: Dict) -> None:
        """보안 검사 함수 추가"""
        # JWT 인증
        if security_controls.get("authentication", {}).get("method") == "JWT":
            jwt_fn = """fn verify_token(token: string) -> Result<Claims, Error> {
    // JWT 검증 (HS256)
    return Err("invalid_token".to_string());
}"""
            module.functions.append(jwt_fn)

        # RBAC
        if security_controls.get("authorization", {}).get("type") == "RBAC":
            rbac_fn = """fn check_permission(claims: Claims, required_role: string) -> Result<bool, Error> {
    // 역할 기반 권한 확인
    return Ok(true);
}"""
            module.functions.append(rbac_fn)

        # 입력 검증
        validation_fn = """fn validate_input(input: string) -> Result<string, ValidationError> {
    // 입력 검증
    return Ok(input);
}"""
        module.functions.append(validation_fn)


# ============ 데모 ============

def demo():
    """Stage 3 데모"""
    from architecture_designer import ArchitectureDesigner

    print("\n" + "█"*80)
    print("█" + " "*78 + "█")
    print("█" + " "*20 + "🚀 STAGE 3: INTELLIGENT CODE GENERATOR" + " "*20 + "█")
    print("█" + " "*78 + "█")
    print("█"*80)

    designer = ArchitectureDesigner()
    architecture = designer.design_todo_app()

    generator = IntelligentCodeGenerator()
    result = generator.generate(architecture)

    print("\n" + "="*70)
    print("생성 결과")
    print("="*70)

    print(f"\n📦 모듈 ({len(result.modules)}개):")
    for module in result.modules:
        print(f"  • {module.name}")
        print(f"    - struct: {len(module.structs)}개")
        print(f"    - functions: {len(module.functions)}개")

    print(f"\n🧪 테스트 케이스: {len(result.test_cases)}개")
    print(f"  첫 5개:")
    for test in result.test_cases[:5]:
        print(f"    • {test['name']}")

    print(f"\n🐳 Docker Compose: {len(result.deployment_config.split(chr(10)))}줄")

    print(f"\n📊 메타데이터:")
    for key, value in result.generation_metadata.items():
        print(f"  {key}: {value}")

    # 공유 모듈 코드 일부 출력
    print("\n" + "="*70)
    print("생성된 FV-Lang 코드 (공유 모듈 일부)")
