    if len(code.split("\n")) > 30:
        print(f"\n... ({len(code.split(chr(10)))} 줄 중 처음 30줄)")


if __name__ == "__main__":
    demo()

    print("\n" + "="*70)
    print("✅ Intelligent Code Generator v1.0")
    print("="*70)
